const shell=['index.html','manifest.json'];
const pathOf=u=>{const p=new URL(u,location.href).pathname.replace(/^.*\/Shiwani-portfolio\//,'').replace(/^\//,'');return p===''?'index.html':p};
async function putFresh(c,path){const r=await fetch(path,{cache:'reload'});if(r.ok)await c.put(path,r);return r.ok}
self.addEventListener('install',e=>{e.waitUntil((async()=>{const c=await caches.open(CACHE);for(const p of shell){try{await putFresh(c,p)}catch(err){}}await self.skipWaiting()})())});
self.addEventListener('activate',e=>{e.waitUntil((async()=>{for(const k of await caches.keys())if(k!==CACHE)await caches.delete(k);await self.clients.claim();await syncIfSaved()})())});
self.addEventListener('fetch',e=>{
  if(e.request.method!=='GET')return;
  const u=new URL(e.request.url);if(u.origin!==location.origin)return;
  if(e.request.mode==='navigate'){
    e.respondWith((async()=>{const c=await caches.open(CACHE);try{const r=await fetch(e.request,{cache:'no-cache'});if(r.ok)c.put('index.html',r.clone()).catch(()=>{});return r}catch(err){return (await c.match('index.html'))||Response.error()}})());
    return;
  }
  e.respondWith((async()=>{const c=await caches.open(CACHE);const hit=await c.match(e.request,{ignoreSearch:true,ignoreVary:true});if(hit)return hit;
    try{const r=await fetch(e.request);if(r.ok&&r.type==='basic')c.put(pathOf(e.request.url),r.clone()).catch(()=>{});return r}catch(err){return Response.error()}})());
});
async function storedManifest(c){const m=await c.match(MKEY);if(!m)return null;try{return await m.json()}catch(e){return null}}
async function saveManifest(c){await c.put(MKEY,new Response(JSON.stringify(Object.fromEntries(ALL)),{headers:{'content-type':'application/json'}}))}
async function fetchAll(c,list,force,onProgress){let i=0,done=0;const worker=async()=>{while(i<list.length){const p=list[i++];try{if(force||!(await c.match(p))){const r=await fetch(p,{cache:force?'reload':'no-cache'});if(r.ok)await c.put(p,r)}}catch(e){}done++;if(onProgress)onProgress(done)}};await Promise.all(Array.from({length:6},worker))}
async function precache(client){const c=await caches.open(CACHE);const total=ALL.length;await fetchAll(c,ALL.map(a=>a[0]),false,d=>{if(d%25===0||d===total)client.postMessage({type:'progress',done:d,total})});await saveManifest(c);client.postMessage({type:'done',total})}
async function syncIfSaved(){const c=await caches.open(CACHE);const old=await storedManifest(c);if(!old)return;const cur=Object.fromEntries(ALL);const changed=ALL.filter(([p,h])=>old[p]!==h).map(a=>a[0]);const removed=Object.keys(old).filter(p=>!(p in cur));for(const p of removed)await c.delete(p);await fetchAll(c,changed,true);await saveManifest(c);const cs=await self.clients.matchAll({type:'window'});cs.forEach(cl=>status(cl))}
async function status(client){const c=await caches.open(CACHE);const m=await storedManifest(c);let missing=0;if(m){for(const [p] of ALL){if(!(await c.match(p)))missing++}}client.postMessage({type:'status',saved:!!m,missing,total:ALL.length,complete:!!m&&missing===0})}
self.addEventListener('message',e=>{const t=e.data&&e.data.type;if(t==='precache')e.waitUntil(precache(e.source));if(t==='status')e.waitUntil(status(e.source))});
